let phone = $input.item.json.phone;
let shop_sender = $input.item.json.shop_sender;
let name = $input.item.json.name;
let service = $input.item.json.service;
let professional = $input.item.json.professional;
let datetime = $input.item.json.datetime;

// 1. Si no hay teléfono, detenemos el flujo para evitar errores
// Pero permitimos seguir si es solo prueba, aunque YCloud fallará sin destinatario
if (!phone) {
  return [];
}

// 2. Limpieza del teléfono del cliente
const cleaningRegex = /[^\d]/g;
let cleanPhone = phone.toString().replace(cleaningRegex, '');

if (cleanPhone.startsWith('0')) {
  cleanPhone = cleanPhone.substring(1);
}

// Ensure Argentina code if missing (adjust if you need international support)
if (!cleanPhone.startsWith('54')) {
  cleanPhone = '54' + cleanPhone;
}

// 3. Limpieza del teléfono del comercio (sender)
let cleanSender = '';
if (shop_sender) {
  cleanSender = shop_sender.toString().replace(cleaningRegex, '');
} else {
  cleanSender = '5493586548065'; // Fallback por defecto
}

// 4. Lógica de Fecha y Hora
let formattedDate = '';
let formattedTime = '';

if (datetime) {
  const separator = datetime.includes('T') ? 'T' : ' ';
  const [datePart, timePart] = datetime.split(separator);
  if (datePart) {
    const [year, month, day] = datePart.split('-');
    formattedDate = `${day}/${month}/${year}`;
  }
  if (timePart) {
    // Take HH:MM (first 5 chars)
    formattedTime = timePart.substring(0, 5);
  }
}

// 5. Salida final
return {
  json: {
    sender: cleanSender,
    recipient: cleanPhone,
    p1_name: name || 'Cliente',
    p2_date: formattedDate,
    p3_time: formattedTime,
    p4_service: service || 'Servicio',
    p5_prof: professional || 'Profesional'
  }
};
